    INSERT INTO dbo.[ref_reference] ([id], [norme], [reference], [genre], [intitule], [citation], [lu_sur_piece], [page_piece], [piece_reference], [lu_le], [modifie_par], [modifie_le], [abroge_le], [abroge_par]) VALUES
        (N'1',N'ANC2020-07',N'113-1',N'ARTICLE',N'Principes comptables',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'2',N'NP2300',N'16',N'PARAGRAPHE',N'Documentation des travaux',N'L''expert-comptable constitue un dossier de travail contenant la documentation de ses travaux et notamment les elements importants sur lesquels se fondent ses conclusions.',N'1',N'92',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'3',N'NP2300',N'17',N'PARAGRAPHE',N'Rapport',N'Le rapport emis a l''issue d''une mission de presentation prend la forme d''une attestation qui comporte une conclusion exprimant une assurance formulee sous une forme negative sur la coherence et la vraisemblance des comptes pris dans leur ensemble. Les comptes sont annexes a l''attestation.',N'1',N'92',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'4',N'NP2300',N'18',N'PARAGRAPHE',N'Formulation de la conclusion',N'L''expert-comptable formule dans l''attestation : une conclusion favorable sans observation ; ou une conclusion favorable assortie d''une ou de plusieurs observations ; ou un refus d''attester.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'5',N'NPMQ',N'18-20',N'PARAGRAPHE',N'Acceptation et maintien de relations clients, des missions et activites',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'6',N'NP2300',N'19',N'PARAGRAPHE',N'Conclusion favorable sans observation',N'L''expert-comptable formule une conclusion sans observation lorsqu''il a pu mettre en oeuvre sans limitation toutes les diligences correspondant a une mission de presentation et qu''il n''a releve, au cours de ses travaux, aucun element de nature a remettre en cause la coherence et la vraisemblance des comptes pris dans leur ensemble.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'7',N'NP2300',N'20',N'PARAGRAPHE',N'Conclusion favorable avec observations',N'L''expert-comptable formule une conclusion avec observations lorsqu''il a rencontre au cours de sa mission des limitations dans ses diligences ; ou qu''il a releve une ou plusieurs incertitudes affectant les comptes ; ou qu''il est en desaccord avec le client sur une ou des options prises par ce dernier ; et qu''il estime toutefois que les incidences de ces faits sur les comptes ne sont pas suffisamment significatives pour refuser d''attester.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'8',N'NP2300',N'21',N'PARAGRAPHE',N'Refus d''attester',N'L''expert-comptable exprime un refus d''attester lorsqu''il estime que les incidences sur les comptes des faits releves, incoherences multiples, limitations dans ses diligences, incertitudes ou desaccords, sont significatives.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'9',N'ANC2020-07',N'211-5',N'ARTICLE',N'Valorisation des actifs et passifs eligibles a la valeur actuelle',N'Posterieurement a la date d''entree dans le patrimoine, les actifs et passifs eligibles sont valorises a la valeur actuelle, qui correspond a leur valeur probable de negociation hors frais de cession.',N'1',N'15',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'10',N'ANC2020-07',N'211-6',N'ARTICLE',N'Valeur actuelle des actifs et passifs eligibles',N'L''OPC a capital variable valorise les actifs et passifs eligibles, par famille d''actifs, a la valeur actuelle, selon des modalites appliquees de maniere permanente. Les hypotheses relatives a la valorisation des actifs ou passifs eligibles sont arretees par la societe de gestion. Une information sur la methode d''evaluation et les hypotheses retenues est donnee dans l''annexe.',N'1',N'15',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'11',N'ANC2020-07',N'212-4',N'ARTICLE',N'Valeur actuelle des titres financiers',N'Posterieurement a leur date d''entree dans le patrimoine, les titres financiers sont valorises a leur valeur actuelle.',N'1',N'19',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'12',N'ANC2020-07',N'212-5',N'ARTICLE',N'Valeur actuelle des titres de creances negociables',N'Posterieurement a leur date d''entree dans le patrimoine, les titres de creances negociables sont valorises, en l''absence de transactions significatives, en appliquant une methode actuarielle : les taux retenus sont ceux des emissions de titres equivalents affectes de la marge de risque liee a l''emetteur. Les autres titres de creances sont valorises selon les modalites arretees par la societe de gestion.',N'1',N'20',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'13',N'ANC2020-07',N'214-3',N'ARTICLE',N'Modalites d''evaluation des parts ou actions d''OPC a capital variable',N'Posterieurement a leur date d''entree dans le patrimoine, les parts ou actions d''OPC sont evaluees a la valeur actuelle qui correspond en principe a la derniere valeur liquidative connue. Lorsque le gerant estime que la derniere valeur connue ne reflete pas la valeur actuelle des droits detenus, il est conduit a corriger cette valeur, sous sa responsabilite, si cette correction a un caractere significatif.',N'1',N'22',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'14',N'ANC2020-07',N'215-1',N'ARTICLE',N'Les depots',N'Posterieurement a la date d''operation de depot, sa valeur actuelle est egale a son nominal augmente ou minore des interets courus acquis a la date de valorisation.',N'1',N'22',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'15',N'ANC2020-07',N'216-5',N'ARTICLE',N'Evaluation des instruments financiers a terme',N'Posterieurement a leur date d''entree dans le patrimoine, les instruments financiers a terme sont valorises a leur valeur actuelle.',N'1',N'23',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'16',N'ANC2020-07',N'216-6',N'ARTICLE',N'Differences d''estimation sur instruments financiers a terme',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'17',N'ANC2020-07',N'217-9',N'ARTICLE',N'Operations de prises en pension livree et assimilees',N'Posterieurement a sa date d''operation, la creance representative de la prise en pension livree est maintenue a sa valeur contractuelle. Toutefois, les operations de pension a taux fixe, non resiliables a tout moment sans cout ni penalite pour l''OPC a capital variable et d''une echeance superieure a trois mois, sont evaluees a la valeur actuelle du contrat.',N'1',N'24',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'18',N'NP2300',N'22',N'PARAGRAPHE',N'Contenu de l''attestation',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'19',N'NPMQ',N'26',N'PARAGRAPHE',N'Realisation des missions et activites',N'Les regles et procedures internes de la structure portent notamment sur : les responsabilites des differents membres de l''equipe participant a la mission ou activite ; la documentation des missions ; les consultations, le cas echeant ; la supervision des missions et la revue des dossiers ; les revues independantes, le cas echeant. Pour l''application des regles et procedures internes, les membres de l''equipe exercent leur jugement professionnel et leur esprit critique.',N'1',N'29',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'20',N'NPMQ',N'27',N'PARAGRAPHE',N'Responsabilite des differents membres de l''equipe participant a la mission',N'Pour toutes les missions realisees dans le cadre de l''article 2 ou de l''alinea 4 de l''article 22 de l''Ordonnance du 19 septembre 1945, le responsable de la mission est un expert-comptable ou un salarie autorise a exercer au titre des articles 83 ter ou 83 quater de ladite ordonnance. Il est le garant de la realisation de la mission et du rapport emis au nom de la structure d''exercice professionnel.',N'1',N'29',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'21',N'NPMQ',N'28',N'PARAGRAPHE',N'Documentation des missions',N'La structure definit des regles, redige et applique des procedures relatives a l''etablissement des dossiers de travail ; destinees a assurer la confidentialite, l''integrite et l''accessibilite de la documentation des missions ; portant sur la conservation de la documentation des missions pendant une duree appropriee.',N'1',N'30',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'22',N'NPMQ',N'29',N'PARAGRAPHE',N'Consultations',N'Le responsable de la mission recourt a une consultation, quand il l''estime necessaire. La structure s''assure que la nature et l''etendue des consultations et les conclusions qui en resultent sont consignees dans la documentation de la mission.',N'1',N'30',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'23',N'NPMQ',N'30',N'PARAGRAPHE',N'Supervision des missions et revue des dossiers',N'La supervision des missions resulte du processus mis en place au sein de la structure destine a s''assurer de leur bon deroulement. La supervision porte sur l''organisation et le suivi de la mission. La supervision releve de la responsabilite du responsable de la mission. La revue des dossiers revet un caractere technique. Elle consiste a examiner un dossier pour s''assurer que les travaux ont ete effectues conformement aux obligations legales et reglementaires applicables ainsi qu''aux exigences des normes professionnelles. La revue de dossier est realisee par une personne ayant la competence appropriee.',N'1',N'30',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'24',N'NPMQ',N'31',N'PARAGRAPHE',N'Revue independante des missions',N'La revue independante de la mission est un processus, qui peut etre mis en place au sein de la structure, destine a donner une evaluation objective des jugements importants retenus par l''equipe affectee a la mission et des conclusions qui en decoulent. La revue independante est realisee par une personne interne ou externe qualifiee.',N'1',N'31',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'25',N'NPMQ',N'32-33',N'PARAGRAPHE',N'Surveillance du systeme de management de la qualite',N'La structure definit et met en oeuvre un processus de surveillance destine a s''assurer que les regles et procedures internes sont pertinentes, adequates, et qu''elles fonctionnent efficacement. La surveillance repose sur une surveillance periodique organisee par la structure, une surveillance continue par le biais notamment des constatations des collaborateurs, clients et parties prenantes, et une surveillance periodique assuree par les instances ordinales lors des controles de qualite.',N'1',N'31',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'26',N'NP2300',N'6',N'PARAGRAPHE',N'Esprit critique, jugement professionnel',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'27',N'NP2300',N'7',N'PARAGRAPHE',N'Prise de connaissance prealable de l''entite',N'Prealablement a l''acceptation de la mission, l''expert-comptable acquiert une connaissance de l''entite, de son evolution recente, de son secteur d''activite et de son environnement.',N'1',N'3',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'28',N'NP2300',N'8',N'PARAGRAPHE',N'La lettre de mission',N'Conformement au Code de deontologie, l''expert-comptable etablit une lettre de mission dans laquelle il definit les termes, les conditions de la mission et les obligations reciproques des parties. Cette lettre constitue un contrat qui a pour objectif principal de definir la mission. Elle facilite la planification des travaux et permet de confirmer l''acceptation ou le maintien de la mission confiee a l''expert-comptable.',N'1',N'3',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'29',N'NP2300',N'9-15',N'PARAGRAPHE',N'Diligences a mettre en oeuvre',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'30',N'NP2300',N'A8-A9',N'PARAGRAPHE',N'Modalites d''application, documentation des travaux',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'31',N'CMF',N'L214-149',N'ARTICLE',N'Evaluation du contrat de credit-bail par un expert independant, fonds professionnel',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'32',N'CMF',N'L214-36',N'ARTICLE',N'Actifs éligibles d''un OPCI, les 10 catégories du I',N'Le I de l''article enumere 10 categories : 1° des immeubles construits ou acquis en vue de la location, ainsi que des meubles meublants ; 2° des parts de societes de personnes qui ne sont pas admises aux negociations ; 3° des parts de societes de personnes autres que celles mentionnees au 2° ; 4° des actions negociees sur un marche ; 5° des parts ou actions d''organisme de placement collectif immobilier ; 6° des titres financiers mentionnes au II de l''article L. 211-1 ; 7° des parts ou actions d''organismes de placement collectif en valeurs mobilieres ; 8° des depots et des instruments financiers liquides ; 9° des liquidites definies par decret en Conseil d''Etat ; 10° des avances en compte courant consenties en application de l''article L. 214-42.',N'1',NULL,N'Légifrance, article L. 214-36 du code monétaire et financier, version en vigueur au 04/09/2026, consulté le 04/09/2026',N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'33',N'CMF',N'L214-51',N'ARTICLE',N'Résultat net de l''exercice d''un OPCI : la somme de 3 catégories',N'Le resultat net de l''exercice d''un organisme de placement collectif immobilier est egal a la somme : 1° Des produits relatifs aux actifs immobiliers, y compris les loyers issus de biens meubles, mentionnes aux 1° a 3° et au 5° du I de l''article L. 214-36 pour la societe de placement a preponderance immobiliere a capital variable et aux 1°, 2° et 5° du I du meme article pour le fonds de placement immobilier, diminues du montant des frais et charges correspondant ; 2° Des produits et remunerations degages par la gestion des autres actifs diminues du montant des frais et charges correspondant ; 3° Des autres produits, diminues des frais de gestion et des autres frais et charges, qui ne peuvent etre directement rattaches aux actifs mentionnes aux 1° et 2°. Les modalites d''affectation des frais et charges des 1° a 3° sont definies par decret. Pour l''application du present article, les produits et plus-values realises par une societe mentionnee au 2° du I de l''article L. 214-36 et par un fonds de placement immobilier, un fonds professionnel de placement immobilier ou un organisme de droit etranger, tels que mentionnes a la derniere phrase du 1° de l''article L. 214-37, sont reputes avoir ete realises par le fonds de placement immobilier a concurrence de ses droits directs ou indirects dans cette societe ou dans ce fonds. Version du 1er janvier 2026.',N'1',N'88',N'Recueil des normes comptables du secteur de la gestion d''actifs, édition du 06/01/2026, page imprimée 87, page 88 du fichier, version du 1er janvier 2026, lu le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'34',N'CMF',N'L214-55',N'ARTICLE',N'Evaluation des actifs immobiliers par des evaluateurs : fonde l''exigence que l''article 211-6 du reglement ANC 2021-09 ne prescrit pas',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'35',N'CMF',N'L214-62',N'ARTICLE',N'Définition de la SPPICAV : forme sociale, siège, rachat des actions et capital',N'La societe de placement a preponderance immobiliere a capital variable est une societe anonyme ou une societe par actions simplifiee a capital variable sous forme de societe par actions simplifiee, autre qu''une societe par actions simplifiee instituee par une seule personne et dont les statuts interdisent expressement la pluralite d''associes, soumise aux regles du present sous-paragraphe. Le siege social et l''administration centrale de la societe sont situes en France. Sous reserve de l''article L. 214-45 et dans les conditions fixees par le reglement general de l''Autorite des marches financiers, les actions sont emises et rachetees a la demande des actionnaires a la valeur liquidative majoree ou diminuee, selon le cas, des frais et commissions. Le montant du capital est egal a tout moment a la valeur de l''actif net de la societe, deduction faite des sommes distribuables definies au I de l''article L. 214-69. Le capital initial ne peut etre inferieur a un montant fixe par decret.',N'1',N'88',N'Recueil des normes comptables du secteur de la gestion d''actifs, édition du 06/01/2026, page imprimée 87, page 88 du fichier, lu le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'36',N'CMF',N'L214-69',N'ARTICLE',N'Sommes distribuables d''une SPPICAV : 85 %, 50 % et l''intégralité',N'I. Les sommes distribuables comprennent le resultat distribuable afferent aux produits, egal au resultat net augmente ou minore du report a nouveau et des comptes de regularisation, et les plus-values de cession d''actifs realisees au cours de l''exercice, nettes de frais et diminuees des moins-values, augmentees des resultats anterieurs. II. La societe distribue a hauteur de 85 % au moins la fraction du resultat distribuable afferent aux produits, avec un abattement forfaitaire egal a 1,5 % du prix de revient des immeubles ; a hauteur de 50 % au moins les plus-values realisees lors de la cession des actifs, au titre de l''exercice suivant ; l''integralite de la fraction afferente aux produits de certaines societes beneficiant d''exonerations. IV. La mise en paiement des sommes distribuables a lieu dans le delai d''un mois apres la tenue de l''assemblee generale ayant approuve les comptes. En vigueur depuis le 14/03/2025.',N'1',NULL,N'Légifrance, article L. 214-69 du code monétaire et financier, version en vigueur depuis le 14/03/2025, consulté le 04/09/2026',N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'37',N'CMF',N'L214-81',N'ARTICLE',N'Sommes distribuables d''un fonds de placement immobilier : 85 % pour les 3 catégories',N'I. Les sommes distribuables par un fonds de placement immobilier au titre d''un exercice sont constituees par : 1° Le resultat distribuable afferent aux produits realises par le fonds, qui est egal au resultat net mentionne a l''article L. 214-51, augmente ou minore du report a nouveau, majore ou diminue du solde des comptes de regularisation tels que definis par decret ; 2° Les plus-values de cession d''actifs mentionnes aux 1° et 2° du I de l''article L. 214-36 et au 5° du meme I tels que definis a la derniere phrase du 1° de l''article L. 214-37, realisees au cours de l''exercice, nettes de frais, majorees ou minorees des plus ou moins-values de meme nature realisees au cours d''exercices anterieurs n''ayant pas fait l''objet d''une distribution et, le cas echeant, diminuees ou augmentees du solde des comptes de regularisation tels que definis par decret ; 3° Les plus-values de cession d''actifs autres que ceux mentionnes aux 1° et 2° du I de l''article L. 214-36 realisees au cours de l''exercice, nettes de frais et diminuees des moins-values nettes de frais realisees au cours du meme exercice, majorees ou minorees des plus ou moins-values de meme nature realisees au cours d''exercices anterieurs n''ayant pas fait l''objet d''une distribution et, le cas echeant, diminuees ou augmentees du solde des comptes de regularisation tels que definis par decret. Pour l''application du I, les produits et plus-values realises par une societe mentionnee au 2° du I de l''article L. 214-36 et par un fonds de placement immobilier, un fonds professionnel de placement immobilier, ou un organisme de droit etranger, tels que mentionnes a la derniere phrase du 1° de l''article L. 214-37, sont reputes realises par le fonds de placement immobilier a concurrence de ses droits directs ou indirects dans cette societe ou dans ce fonds. Les sommes mentionnees aux 1° et 2° peuvent etre distribuees, en tout ou partie, independamment l''une de l''autre. II. Le fonds de placement immobilier distribue : 1° A hauteur de 85 % au moins, la fraction du resultat distribuable au sens du 1° du I relative aux actifs suivants : a) Actifs immobiliers mentionnes au 1° du I de l''article L. 214-36 que le fonds detient directement ou par l''intermediaire, selon le cas, d''une societe mentionnee a l''article L. 214-80 ou d''un fonds de placement immobilier, d''un fonds professionnel de placement immobilier, ou d''un organisme de droit etranger similaire mentionne a la derniere phrase du 1° de l''article L. 214-37, au titre de l''annee de leur realisation. Pour la determination du montant a distribuer, les produits nets sont diminues d''un abattement forfaitaire egal a 1,5 % du prix de revient des immeubles detenus directement par le fonds ; b) Autres actifs que le fonds detient directement ou par l''intermediaire d''une societe mentionnee a l''article L. 214-80 au titre de l''exercice de leur realisation ; 2° A hauteur de 85 % au moins, les plus-values distribuables, mentionnees au 2° du I, realisees au cours de l''exercice, diminuees le cas echeant de l''abattement prevu au I de l''article 150 VC du code general des impots, realisees par le fonds ou par l''intermediaire d''une societe mentionnee a l''article L. 214-80 : a) Lors de la cession des actifs immobiliers mentionnes au 1° du I de l''article L. 214-36 au titre de l''annee de cession ; b) Lors de la cession des parts de societes mentionnees au 2° du I de l''article L. 214-36, au titre de l''annee de cession ; c) Lors de la cession des parts de fonds de placement immobilier, de fonds professionnel de placement immobilier, ou d''organismes de droit etranger, tels que mentionnes a la derniere phrase du 1° de l''article L. 214-37 ; 3° A hauteur de 85 % au moins, les plus-values realisees directement par le fonds et par l''intermediaire, selon le cas, d''une societe mentionnee a l''article L. 214-80, d''un fonds de placement immobilier, d''un fonds professionnel de placement immobilier, ou d''un organisme de droit etranger, tels que mentionnes a la derniere phrase du 1° de l''article L. 214-37, lors de la cession des actifs autres que ceux mentionnes au 2°, au titre de l''exercice de leur realisation. III. La mise en paiement des sommes distribuables est effectuee dans le delai de cinq mois suivant la cloture de l''exercice. Toutefois, la mise en paiement des sommes distribuables au titre des plus-values mentionnees au 2° du II a lieu avant le dernier jour du sixieme mois suivant la cession des actifs concernes.',N'1',NULL,N'Légifrance, article L. 214-81 du code monétaire et financier, version en vigueur depuis le 14/03/2025, ordonnance n° 2025-230 du 12 mars 2025 articles 3 et 7, consulté le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'38',N'CMF',N'R214-81',N'ARTICLE',N'Immeubles éligibles à l''actif d''un OPCI : les 3 cas du 1° du I de L. 214-36',N'Les immeubles mentionnes au 1° du I de l''article L. 214-36 eligibles a l''actif d''un organisme de placement collectif immobilier sont : 1° Les immeubles loues ou offerts a la location a la date de leur acquisition par l''organisme ou par toute personne morale ayant conclu une convention d''usufruit conformement au chapitre III du titre V du livre II du code de la construction et de l''habitation ; 2° Les immeubles que l''organisme fait construire, rehabiliter ou renover en vue de leur location par lui-meme ou par toute personne morale ayant conclu une convention d''usufruit conformement au meme chapitre ; 3° Les terrains nus situes dans une zone urbaine ou a urbaniser delimitee par un document d''urbanisme. Les immeubles mentionnes au 2° peuvent etre acquis par des contrats de vente a terme, de vente en l''etat futur d''achevement ou de vente d''immeubles a renover ou a rehabiliter. Les immeubles mentionnes au 1°, lorsqu''ils font l''objet d''une convention d''usufruit, ne peuvent avoir ete acquis aupres de l''un des organismes mentionnes aux articles L. 365-2, L. 411-2 ou L. 481-1 du meme code. L''organisme peut conclure des contrats de promotion immobiliere en vue de la construction d''immeubles mentionnes au 2°. En vigueur depuis le 08/09/2014, decret n° 2014-1011 du 5 septembre 2014, article 2.',N'1',NULL,N'Légifrance, article R. 214-81 du code monétaire et financier, version en vigueur depuis le 08/09/2014, consulté le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'39',N'ANC2021-09',N'111-1',N'ARTICLE',N'Champ d’application',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'40',N'ANC2021-09',N'112-1',N'ARTICLE',N'Actifs et passifs éligibles',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'41',N'ANC2021-09',N'113-1',N'ARTICLE',N'Principes comptables',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'42',N'ANC2021-09',N'113-2',N'ARTICLE',N'Valorisation des actifs et passifs à la valeur actuelle',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
