        (N'86',N'ANC2021-09',N'322-10',N'ARTICLE',N'Frais de gestion',N'Les frais de gestion comprennent l''ensemble des depenses engagees pour le fonctionnement de l''OPCI, directement ou indirectement, y compris les commissions de gestion, les commissions de surperformance et les frais de liquidation a l''occasion de sa dissolution. En revanche ces frais ne comprennent pas les frais d''acquisition et de cession.',N'1',N'94',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'87',N'ANC2021-09',N'322-11',N'ARTICLE',N'Autres produits et autres charges',N'Les autres produits et autres charges comprennent les produits et charges qui ne peuvent etre rattaches ni a l''activite immobiliere ni aux operations financieres.',N'1',N'94',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
