        (N'93',N'ANC2021-09',N'322-3',N'ARTICLE',N'Résultat de l’activité immobilière',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'94',N'ANC2021-09',N'322-4',N'ARTICLE',N'Produits de l''activite immobiliere',N'Les produits de l''activite immobiliere relatifs aux actifs a caractere immobilier sont constitues des produits immobiliers sur les immeubles et droits reels detenus en direct, des produits sur parts et actions des entites a caractere immobilier hors revenus des SIC, du produit de la garantie locative, des reprises de provisions rattachees a l''activite immobiliere, et des produits sur autres actifs immobiliers.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'95',N'ANC2021-09',N'322-5',N'ARTICLE',N'Charges de l''activite immobiliere',N'Les charges de l''activite immobiliere sont constituees des charges immobilieres sur les actifs detenus en direct, des charges sur parts et actions des entites a caractere immobilier, du cout de la garantie locative, des redevances de credit-bail, des frais d''audits et d''etudes, des dotations aux provisions rattachees, des charges sur autres actifs immobiliers, et DES CHARGES D''EMPRUNT LIEES A DES ACTIFS IMMOBILIERS.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'96',N'ANC2021-09',N'322-6',N'ARTICLE',N'Frais d’audit, d’étude et de recherche liés à des projets n’ayant pas abouti',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'97',N'ANC2021-09',N'322-7',N'ARTICLE',N'Resultat sur operations financieres',N'Le resultat sur operations financieres reflete les produits nets de charges issus des autres actifs et passifs financiers, autres que les actifs a caractere immobilier. Il comprend egalement les charges financieres liees aux emprunts AUTRES que ceux realises pour l''acquisition d''actifs a caractere immobilier.',N'1',N'93',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'98',N'ANC2021-09',N'322-8',N'ARTICLE',N'Produits sur opérations financières',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'99',N'ANC2021-09',N'322-9',N'ARTICLE',N'Charges sur operations financieres',N'Les charges sur les operations financieres relatives aux autres actifs et passifs financiers sont constituees des charges sur les depots et instruments financiers non immobiliers, et des autres charges financieres, dont notamment les charges d''emprunts qui ne sont pas affectes a des actifs immobiliers.',N'1',N'94',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
