        (N'135',N'ANC2021-09',N'512-4',N'ARTICLE',N'Informations devant figurer dans l’annexe',NULL,N'0',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
        (N'136',N'PCG',N'1214-45',N'ARTICLE',N'Groupe et associes',N'Le compte 451 « Groupe » enregistre a son debit le montant des fonds avances directement ou indirectement de facon temporaire par l''entite aux societes du groupe, et a son credit le montant des fonds mis directement ou indirectement a disposition de l''entite par les societes du groupe. Le compte 455 « Associes - Comptes courants » enregistre a son credit le montant des fonds mis ou laisses temporairement a la disposition de l''entite par les associes.',N'1',N'168',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'137',N'PCG',N'164',N'TITRE',N'Emprunts aupres des etablissements de credit',N'16 Emprunts et dettes assimilees, fonds non remboursables et avances conditionnees / 164 Emprunts aupres des etablissements de credit si non-inscrits dans le compte 167 / 1648 Interets courus.',N'1',N'134',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'138',N'PCG',N'211',N'TITRE',N'Terrains',N'21 Immobilisations corporelles / 211 Terrains / 2111 Terrains nus / 2112 Terrains amenages / 2115 Terrains batis.',N'1',N'135',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'139',N'PCG',N'213',N'TITRE',N'Constructions',N'21 Immobilisations corporelles / 211 Terrains / 213 Constructions / 2131 Batiments / 2135 Installations generales, agencements, amenagements des constructions / 2138 Ouvrages d''infrastructure.',N'1',N'135',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'140',N'PCG',N'316-1',N'ARTICLE',N'Avances conditionnees',N'Les avances conditionnees sont des avances accordees par l''Etat, un organisme public, une societe ou un etablissement controle par l''Etat ou un organisme public et dont le remboursement est conditionne par le succes du projet finance. Ces interets courus sont debites dans le compte 661 - Charges d''interets. Lorsque la remuneration de l''avance n''est pas conditionnee, elle est inscrite en dettes.',N'1',N'33',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'141',N'PCG',N'4551',N'TITRE',N'Associes - Comptes courants, principal',N'455 Associes - Comptes courants / 4551 Principal / 4558 Interets courus. Nomenclature du plan de comptes.',N'1',N'140',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'142',N'PCG',N'4558',N'TITRE',N'Associes - Comptes courants, interets courus',N'455 Associes - Comptes courants / 4558 Interets courus.',N'1',N'140',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'143',N'PCG',N'661',N'TITRE',N'Charges d''interets',N'661 Charges d''interets / 6611 Interets des emprunts et dettes / 66116 Interets des emprunts et dettes.',N'1',N'145',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'144',N'PCG',N'6615',N'TITRE',N'Interets des comptes courants et des depots crediteurs',N'661 Charges d''interets / 6615 Interets des comptes courants et des depots crediteurs / 6616 Interets bancaires et sur operations de financement.',N'1',N'145',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'145',N'NPLAB',N'19',N'PARAGRAPHE',N'Les 4 criteres de la classification des risques',N'La classification des risques de la structure s''opere au moins selon les quatre criteres suivants : les caracteristiques des clients ; l''activite des clients ; la localisation des clients, en prenant en compte egalement le territoire d''origine ou de destination des fonds ; les missions proposees par la structure.',N'1',N'8',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'146',N'NPLAB',N'21',N'PARAGRAPHE',N'Les 2 niveaux de vigilance',N'Le systeme d''identification et d''evaluation des risques retient deux niveaux pour la vigilance applicable au cours de la relation d''affaires : une vigilance standard lorsque le degre d''exposition aux risques est faible ou moyen ; une vigilance renforcee lorsque le degre d''exposition aux risques est eleve.',N'1',N'9',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'147',N'NPLAB',N'23',N'PARAGRAPHE',N'Le reexamen des niveaux de risque et de vigilance',N'Le niveau de risque et le niveau de vigilance sont reexamines de facon a conserver une connaissance appropriee de la relation d''affaires. Ce reexamen est documente.',N'1',N'9',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'148',N'NPLAB',N'24',N'PARAGRAPHE',N'L''entree en relation d''affaires',N'Une relation d''affaires est nouee avant la signature de la lettre de mission, lorsque la structure engage une relation professionnelle qui est censee, au moment ou le contact est etabli, s''inscrire dans une certaine duree.',N'1',N'9',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'149',N'NPLAB',N'26a',N'PARAGRAPHE',N'L''objet et la nature de la relation d''affaires',N'Avant d''entrer en relation d''affaires, le responsable de la mission recueille et analyse les elements d''information necessaires a la connaissance de l''objet et de la nature de la relation d''affaires. Ces actions sont adaptees en fonction du niveau de vigilance attribue au client tel qu''il resulte des dispositifs d''identification et d''evaluation du risque.',N'1',N'10',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'150',N'NPLAB',N'28',N'PARAGRAPHE',N'L''identification du client personne physique',N'Lorsque le client est une personne physique, presente lors de l''identification, il est recueilli ses nom et prenoms, ainsi que ses date et lieu de naissance. La verification de son identite est effectuee en recourant a des moyens d''identification electronique prevus par le code monetaire et financier ou par la presentation d''un document officiel en cours de validite comportant sa photographie dont il est conserve une copie.',N'1',N'11',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'151',N'NPLAB',N'29',N'PARAGRAPHE',N'L''identification du client personne morale',N'Lorsque le client est une personne morale, dont le representant habilite est present lors de l''identification, il est recueilli sa forme juridique, sa denomination, son numero d''immatriculation ainsi que l''adresse de son siege social et celle du lieu de la direction effective de l''activite, si celle-ci est differente. La verification de l''identite de cette personne morale est effectuee en obtenant communication de l''original ou de la copie de tout acte ou extrait de registre officiel datant de moins de trois mois ou extrait du journal officiel.',N'1',N'11',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'152',N'NPLAB',N'31a',N'PARAGRAPHE',N'L''identification du beneficiaire effectif',N'L''identification d''un beneficiaire effectif necessite de recueillir ses nom et prenoms ainsi que ses date et lieu de naissance. Lorsque le client est une societe ou une entite etablie en France et immatriculee au registre du commerce et des societes, la verification de l''identite du ou des beneficiaires effectifs s''opere par la consultation du registre des beneficiaires effectifs.',N'1',N'11',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'153',N'NPLAB',N'31b',N'PARAGRAPHE',N'La verification de l''identite du beneficiaire effectif',N'Si les informations contenues dans le registre des beneficiaires effectifs ne permettent pas la verification, ou pour toute autre personne morale, la verification s''opere par des mesures adaptees au risque de blanchiment de capitaux et de financement du terrorisme.',N'1',N'12',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'154',N'NPLAB',N'34',N'PARAGRAPHE',N'Le client non physiquement present',N'Lorsque le client ou son representant dument habilite n''est pas physiquement present aux fins de l''identification au moment de l''etablissement de la relation d''affaires, deux des mesures d''identification prevues a l''article R. 561-5-2 du meme code sont mises en oeuvre avant l''entree en relation d''affaires.',N'1',N'13',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'155',N'NPLAB',N'35',N'PARAGRAPHE',N'La personne politiquement exposee',N'Lorsque le client ou son beneficiaire effectif est une personne politiquement exposee, la decision de nouer la relation d''affaires avec cette personne est prise par un membre de l''organe executif de la structure ou toute personne habilitee a cet effet par l''organe executif. Le recueil avant l''entree en relation d''affaires des informations relatives a l''objet et a la nature de cette relation est complete de la recherche sur l''origine du patrimoine et des fonds.',N'1',N'13',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'156',N'NPLAB',N'36',N'PARAGRAPHE',N'Le territoire liste par le GAFI ou la Commission europeenne',N'Lorsque la structure d''exercice professionnel realise une mission pour des personnes physiques ou morales, domiciliees, enregistrees ou etablies dans un Etat ou un territoire figurant sur les listes publiees par le Groupe d''action financiere parmi ceux dont la legislation ou les pratiques font obstacle a la lutte contre le blanchiment, ou par la Commission europeenne en application de l''article 9 de la directive (UE) 2015/849 du 20 mai 2015, le responsable de la mission met en oeuvre les mesures de vigilance complementaires prevues par l''article R. 561-20-4 du CMF.',N'1',N'14',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'157',N'NPLAB',N'39',N'PARAGRAPHE',N'La connaissance actualisee de la relation d''affaires',N'L''equipe affectee a la mission recueille, met a jour et analyse les elements d''information qui permettent de conserver une connaissance appropriee et actualisee de sa relation d''affaires. La nature et l''etendue des informations collectees ainsi que la frequence de la mise a jour de ces informations et l''etendue des analyses menees sont adaptees au risque de blanchiment de capitaux et de financement du terrorisme presente par la relation d''affaires.',N'1',N'14',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'158',N'NPLAB',N'40',N'PARAGRAPHE',N'L''identification devenue inexacte ou non pertinente',N'Lorsque l''equipe affectee a la mission a de bonnes raisons de penser que les elements d''identification du client, et le cas echeant de son ou ses beneficiaires effectifs, ne sont plus exacts ou pertinents, elle procede de nouveau a l''identification et a la verification de leur identite. Si elle n''est plus en mesure d''identifier le client, la structure met un terme a la relation d''affaires et l''expert-comptable peut transmettre a TRACFIN une declaration de soupcon si les conditions en sont reunies.',N'1',N'15',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'159',N'NPLAB',N'42',N'PARAGRAPHE',N'L''examen renforce d''une operation atypique',N'L''equipe affectee a la mission effectue un examen renforce de toute operation particulierement complexe ou d''un montant inhabituellement eleve ou ne paraissant pas avoir de justification economique ou d''objet licite. Dans ce cas, elle se renseigne aupres du client sur l''origine des fonds et la destination de ces sommes ainsi que sur l''objet de l''operation et l''identite de la personne qui en beneficie. Les resultats de l''examen renforce sont consignes par ecrit.',N'1',N'15',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'160',N'NPLAB',N'45',N'PARAGRAPHE',N'L''obligation de declaration a TRACFIN',N'Sauf exception prevue au dernier alinea de ce paragraphe, l''obligation de declaration concerne l''ensemble des missions realisees par l''expert-comptable. Il doit deposer une declaration a TRACFIN portant sur les operations faites par le client ou dont l''expert-comptable aurait eu connaissance a travers ses missions, mettant en jeu des sommes dont il sait, soupconne ou a de bonnes raisons de soupconner qu''elles proviennent d''une infraction.',N'1',N'16',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'161',N'NPMQ',N'16',N'PARAGRAPHE',N'Independance en toute circonstance',N'La structure, son personnel technique ainsi que, le cas echeant, toute personne externe intervenant sur la mission ou sur l''activite conservent leur independance en toute circonstance.',N'1',N'4',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'162',N'NPMQ',N'17',N'PARAGRAPHE',N'Confirmation ecrite du respect des regles d''independance',N'La structure obtient periodiquement de tout son personnel technique une confirmation ecrite du respect des regles internes liees a l''independance.',N'1',N'5',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'163',N'NPMQ',N'18',N'PARAGRAPHE',N'Acceptation et maintien de relations clients, des missions et activites',N'La structure definit des regles, redige et applique des procedures qui lui permettent d''accepter ou de maintenir les missions et activites si : elle peut se conformer aux obligations legales et reglementaires applicables ainsi qu''aux exigences des normes professionnelles ; compte tenu des informations dont elle a connaissance, elle ne conclut pas a un manque d''integrite du client ; elle a la competence, le temps et les ressources necessaires pour realiser la mission ou l''activite.',N'1',N'5',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'164',N'NPMQ',N'19',N'PARAGRAPHE',N'Les dispositions que les regles d''acceptation prevoient',N'La structure obtient les informations qu''elle estime necessaires pour accepter ou se maintenir sur une mission ou une activite ; si elle identifie un conflit d''interets potentiel, elle en tire les consequences appropriees, conformement au Code de deontologie ; si des difficultes ont ete identifiees et que la structure decide toutefois d''accepter ou de maintenir la mission, elle documente la maniere dont ces difficultes ont ete traitees.',N'1',N'5',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'165',N'NPMQ',N'20',N'PARAGRAPHE',N'Le maintien face a une information connue a posteriori',N'La structure definit des regles, redige et applique des procedures qui traitent du maintien des missions dans les situations ou elle a connaissance d''informations a posteriori qui l''auraient conduite a refuser la mission si elle en avait eu connaissance plus tot. Ces regles et procedures prennent en compte les obligations legales et professionnelles qui s''imposent dans cette situation ; la possibilite de mettre fin eventuellement a la relation client.',N'1',N'6',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'166',N'NPMQ',N'21',N'PARAGRAPHE',N'Les ressources de la structure',N'La structure definit des regles, redige et applique des procedures concernant les ressources humaines, technologiques, methodologiques et documentaires.',N'1',N'6',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'167',N'NPMQ',N'22',N'PARAGRAPHE',N'Competences, temps et moyens du personnel technique',N'La structure definit des regles, redige et applique des procedures destinees a s''assurer qu''elle dispose d''un personnel technique interne ou externe ayant les competences, le temps et les moyens necessaires pour realiser ses missions et activites.',N'1',N'6',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'168',N'NPMQ',N'23',N'PARAGRAPHE',N'La designation du responsable de mission',N'La structure designe, pour chaque mission, un responsable de mission, dont les responsabilites sont clairement definies et lui sont communiquees. Elle s''assure qu''il possede la competence, le temps, les moyens, l''autorite necessaires et la capacite d''exercer son jugement professionnel.',N'1',N'6',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'169',N'NPMQ',N'24',N'PARAGRAPHE',N'Les ressources technologiques',N'La structure dispose des ressources technologiques appropriees et s''assure periodiquement de leur efficacite pour realiser ses missions et activites.',N'1',N'7',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'170',N'NPMQ',N'25',N'PARAGRAPHE',N'Les ressources methodologiques et documentaires',N'La structure dispose des ressources methodologiques et documentaires pertinentes pour realiser ses missions et activites.',N'1',N'7',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'171',N'NPMQ',N'A18-1',N'PARAGRAPHE',N'Apprecier l''integrite du client',N'Pour apprecier l''integrite du client, la structure peut notamment prendre en consideration l''identite et la reputation en affaires de ses principaux proprietaires et dirigeants, la nature de ses activites, une interpretation agressive des normes comptables, une pression excessive sur le niveau des honoraires, une limitation inappropriee de l''etendue des travaux et les indices d''implication dans des operations de blanchiment.',N'1',N'15',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'172',N'NPMQ',N'A18-2',N'PARAGRAPHE',N'Apprecier la competence, le temps et les ressources',N'Afin de determiner si la structure dispose de la competence, des ressources et du temps necessaires, elle prend notamment en consideration la connaissance du secteur, du sujet et de la reglementation par les intervenants, la disponibilite des moyens et le respect des delais convenus avec le client.',N'1',N'16',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'173',N'DEONTO',N'145',N'PARAGRAPHE',N'Competence, conscience professionnelle et independance d''esprit',N'Les personnes mentionnees a l''article 141 exercent leur activite avec competence, conscience professionnelle et independance d''esprit.',N'1',N'4',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'174',N'DEONTO',N'150',N'PARAGRAPHE',N'L''appreciation avant l''acceptation et l''examen periodique',N'Avant d''accepter une mission, les personnes mentionnees a l''article 141 apprecient la possibilite de l''effectuer conformement aux dispositions legislatives et reglementaires applicables, notamment celles du present code, et selon les regles professionnelles definies par le Conseil national de l''ordre. Elles examinent periodiquement, pour leurs missions recurrentes, si des circonstances nouvelles ne remettent pas en cause la poursuite de celles-ci.',N'1',N'5',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'175',N'DEONTO',N'156',N'PARAGRAPHE',N'L''exercice de la mission jusqu''a son terme normal',N'Les personnes mentionnees a l''article 141 doivent exercer leur mission jusqu''a son terme normal. Toutefois, elles peuvent, en s''efforcant de ne pas porter prejudice a leur client ou adherent, y mettre fin pour des motifs justes et raisonnables.',N'1',N'9',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'176',N'DEONTO',N'157',N'PARAGRAPHE',N'L''obligation de denoncer le contrat',N'Les personnes mentionnees a l''article 141 ont l''obligation de denoncer le contrat qui les lie a leur client ou adherent des la survenance d''un evenement susceptible de les placer en situation de conflit d''interets.',N'1',N'9',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'177',N'DEONTO',N'163',N'PARAGRAPHE',N'Le remplacement d''un confrere',N'Les personnes mentionnees a l''article 141 appelees par un client ou adherent a remplacer un confrere ne peuvent accepter leur mission qu''apres en avoir informe ce dernier.',N'1',N'11',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'178',N'NP2300',N'5',N'PARAGRAPHE',N'La responsabilite de la direction de l''entite',N'Les comptes sont etablis sous la responsabilite de la direction de l''entite, conformement au referentiel comptable qui lui est applicable. En consequence, la direction de l''entite est responsable a l''egard des tiers de l''exhaustivite, de la fiabilite et de l''exactitude des informations comptables et financieres ainsi que des procedures de controle interne concourant a l''etablissement des comptes. Des lors, la direction de l''entite est responsable des informations communiquees a l''expert-comptable pour les besoins de sa mission.',N'1',N'3',NULL,N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'179',N'CMF',N'L214-37',N'ARTICLE',N'Composition de l''actif : 60 %, 51 % et 5 %',N'Dans les conditions fixees par decret en Conseil d''Etat, l''actif d''un organisme de placement collectif immobilier est compose : 1° A hauteur de 60 % au moins d''actifs immobiliers. Dans le cas de la societe de placement a preponderance immobiliere a capital variable, ces actifs immobiliers sont ceux mentionnes aux 1° a 5° du I de l''article L. 214-36, les actifs mentionnes aux 1° a 3° et au 5° du I de l''article precite devant representer au minimum 51 % de l''actif ; 2° A hauteur de 5 % au moins d''actifs mentionnes au 8° et au 9° du I de l''article L. 214-36. Ces actifs doivent etre libres de toutes suretes ou droits au profit de tiers. En vigueur depuis le 28/07/2013.',N'1',NULL,N'Légifrance, article L. 214-37 du code monétaire et financier, version en vigueur depuis le 28/07/2013, consulté le 04/09/2026',N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'180',N'CMF',N'L214-39',N'ARTICLE',N'Limite d''endettement de 40 %, filiales comprises à la quote-part',N'Un organisme de placement collectif immobilier peut contracter des emprunts dans la limite de 40 % de la valeur des actifs immobiliers mentionnes aux 1° a 3° et au 5° du I de l''article L. 214-36. Pour l''appreciation de cette limite, il est tenu compte de l''ensemble des emprunts et dettes souscrits par l''organisme, par les societes mentionnees aux 2° et 3° du I de l''article L. 214-36 et par les organismes mentionnes au 5° du meme I, a concurrence du pourcentage de participation detenue directement ou indirectement dans ces societes ou organismes. En vigueur depuis le 28/07/2013.',N'1',NULL,N'Légifrance, article L. 214-39 du code monétaire et financier, version en vigueur depuis le 28/07/2013, consulté le 04/09/2026',N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'181',N'CMF',N'R214-125',N'ARTICLE',N'Délai de 75 jours pour la mise à disposition des comptes',N'La mise a la disposition du commissaire aux comptes des comptes annuels et du rapport de gestion mentionnes a l''article L. 214-50 s''effectue dans un delai de soixante-quinze jours suivant la cloture de l''exercice. En vigueur depuis le 21/07/2025, derniere modification par le decret n° 2025-673 du 18 juillet 2025.',N'1',NULL,N'Légifrance, article R. 214-125 du code monétaire et financier, version en vigueur au 04/09/2026, consulté le 04/09/2026',N'2026-09-04',NULL,NULL,NULL,NULL),
        (N'182',N'CMF',N'R214-83',N'ARTICLE',N'Éligibilité des participations : 3 conditions cumulatives et 5 cas de relation',N'Les participations directes ou indirectes dans des societes mentionnees aux 2° et 3° du I de l''article L. 214-36 ne sont eligibles a l''actif d''un OPCI que si les trois conditions suivantes sont satisfaites : 1° ces societes etablissent des comptes annuels et des comptes intermediaires d''une frequence au moins semestrielle ; 2° les immeubles et droits reels a l''actif de ces societes satisfont aux conditions enoncees aux articles R. 214-81 et R. 214-82 ; 3° les relations correspondent a l''un des cas suivants : a) majorite des droits de vote ; b) designation, pendant deux exercices successifs, de la majorite des membres des organes, presumee au-dela de 40 % des droits de vote si aucun autre associe n''en detient davantage ; c) influence dominante en vertu d''un contrat ou de clauses statutaires ; d) exercice conjoint avec d''autres organismes du 5° du I geres par la meme societe de gestion ou une societe liee au sens de l''article L. 233-3 du code de commerce ; e) engagement ecrit de transmettre les informations necessaires, notamment a l''evaluation des actifs et passifs, au calcul des limites et quotas, de la limite d''endettement de l''article L. 214-39 et des sommes distribuables des articles L. 214-69 et L. 214-81. En vigueur depuis le 31/07/2013, modifie par le decret n° 2013-687 du 25 juillet 2013, article 8.',N'1',NULL,N'Légifrance, article R. 214-83 du code monétaire et financier, version en vigueur depuis le 31/07/2013, texte intégral fourni par le candidat, consulté le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'183',N'CMF',N'R214-82',N'ARTICLE',N'Droits réels éligibles : les 7 catégories du 1° de L. 214-36',N'Les droits reels mentionnes au 1° du 1 de l''article L. 214-36 sont : 1° La propriete, la nue-propriete et l''usufruit ; 2° L''emphyteose ; 3° Les servitudes ; 4° Les droits du preneur d''un bail a construction ou d''un bail a rehabilitation ; 5° Tout droit reel confere par un titre ou par un bail emphyteotique a raison de l''occupation d''une dependance du domaine public de l''Etat, d''une collectivite territoriale, ou d''un etablissement public sur les ouvrages, constructions et installations de caractere immobilier realises sur cette dependance ; 6° Les autres droits de superficie ; 7° Tout droit relevant d''un droit etranger et comparable a l''un des droits mentionnes aux 1° a 6°. En vigueur depuis le 06/08/2025, decret n° 2025-762 du 4 aout 2025, article 3.',N'1',NULL,N'Légifrance, article R. 214-82 du code monétaire et financier, version en vigueur depuis le 06/08/2025, consulté le 05/09/2026',N'2026-09-05',NULL,NULL,NULL,NULL),
        (N'184',N'CMF',N'L214-82',N'ARTICLE',N'ABROGÉ : délai de mise en paiement des plus-values d''un FPI',N'Article ABROGE le 14/03/2025 par l''ordonnance n° 2025-230 du 12 mars 2025, article 3. Il portait le delai de mise en paiement des sommes distribuables au titre des plus-values de cession d''actifs d''un fonds de placement immobilier, fixe au dernier jour du sixieme mois suivant la cession. Cette regle figure desormais au dernier alinea du III de l''article L. 214-81. AUCUN TEXTE DU DOSSIER NE S''Y APPUIE : l''article entre au referentiel pour porter son abrogation, et non pour etre applique.',N'1',NULL,N'Légifrance, article L. 214-82 du code monétaire et financier, mention « ABROGÉ », consulté le 05/09/2026',N'2026-09-05',NULL,NULL,N'2025-03-14',N'installation (abroge_par)');
