-- ref_reference : 184 ligne(s) de referentiel.
-- Rejouable : la table ne se remplit que si elle est vide. Rien n'est efface.
-- Produit depuis la base de reference, ne pas modifier a la main.

IF NOT EXISTS (SELECT 1 FROM dbo.[ref_reference])
BEGIN
    SET IDENTITY_INSERT dbo.[ref_reference] ON;
    SET IDENTITY_INSERT dbo.[ref_reference] OFF;
    PRINT 'ref_reference : ' + CAST(@@ROWCOUNT AS VARCHAR(10)) + ' ligne(s) chargee(s).';
END
ELSE PRINT 'ref_reference : deja chargee, rien a faire.';
GO
